    'لغة لوحة الإدارة' => 'Admin panel language', 'لغة الموقع' => 'Site language', 'نفس لغة اللوحة' => 'Same as the panel', 'تُحقن في وسم html (lang وdir) لكل صفحات الموقع.' => 'Injected into the html tag (lang and dir) of every site page.',
    'العودة للرئيسية' => 'Back to home', 'لا توجد نتائج.' => 'No results.', 'الصفحات' => 'Pages', 'مبني بنظام' => 'Built with', 'بحث: ' => 'Search: ', 'إرسال' => 'Send', 'غير موجود' => 'Not found',
    // login / reset
    'أنشئ نظامك بنفسك' => 'Build your own system', 'نمذجة المحتوى، مصمم صفحات بصري، واستيراد المواقع الجاهزة وربطها ببياناتك، في نظام واحد خفيف.' => 'Content modeling, a visual page designer, and importing ready-made sites bound to your data, in one light system.',
    'أنواع محتوى وحقول بلا حدود' => 'Unlimited content types and fields', 'مصمم صفحات بالسحب والإفلات' => 'Drag-and-drop page designer', 'استيراد موقع جاهز وربط عناصره بالمحتوى' => 'Import a ready-made site and bind its elements to content',
    'نسيت كلمة المرور؟' => 'Forgot your password?', 'إظهار كلمة المرور' => 'Show password', 'استعادة كلمة المرور' => 'Password recovery', 'العودة لتسجيل الدخول' => 'Back to sign in',
    'إن كان هذا البريد مسجلاً لدينا، فقد أرسلنا إليه رابطاً لاختيار كلمة مرور جديدة. الرابط صالح لمدة ساعة.' => 'If this email is registered with us, we sent it a link to choose a new password. The link is valid for one hour.',
    'لم يصلك شيء؟ تحقق من البريد المزعج، أو تأكد من إعدادات البريد في الإعدادات.' => 'Nothing arrived? Check your spam folder, or verify the mail settings in Settings.', 'أدخل بريدك الإلكتروني وسنرسل لك رابطاً لاختيار كلمة مرور جديدة.' => 'Enter your email and we will send you a link to choose a new password.',
    'إرسال رابط الاستعادة' => 'Send reset link', 'كلمة مرور جديدة' => 'New password', 'اختر كلمة مرور جديدة للحساب' => 'Choose a new password for the account', 'حفظ كلمة المرور' => 'Save password', 'رابط الاستعادة غير صالح أو انتهت صلاحيته.' => 'The reset link is invalid or has expired.',
    'اطلب رابطاً جديداً' => 'Request a new link', 'تم تغيير كلمة المرور. سجّل الدخول بكلمة المرور الجديدة.' => 'Password changed. Sign in with your new password.', 'مرحباً {name}،' => 'Hello {name},',
    'وصلنا طلب لاستعادة كلمة المرور لحسابك في «{site}». افتح الرابط التالي لاختيار كلمة مرور جديدة (صالح لمدة ساعة):' => 'We received a request to reset the password of your account at "{site}". Open the link below to choose a new password (valid for one hour):',
    'إن لم تطلب ذلك فتجاهل هذه الرسالة، ولن يتغير شيء.' => 'If you did not request this, ignore this message and nothing will change.',    // factory reset
    'استعادة النظام للوضع الافتراضي' => 'Restore the system to its default state', 'يحذف كل أنواع المحتوى والمدخلات والتصاميم والكتل والنماذج والرسائل والوسائط والمواقع المستوردة والمستخدمين الآخرين ومفاتيح API وWebhooks، ويعيد الإعدادات إلى قيمها الأولى. يبقى حسابك ولغة اللوحة وعنوان الموقع فقط.' => 'Deletes every content type, entry, design, block, form, message, media file, imported site, other users, API keys and webhooks, and resets settings to their initial values. Only your account, the panel language and the site title are kept.',
    'لا يمكن التراجع عن هذا الإجراء.' => 'This action cannot be undone.', 'خذ نسخة احتياطية من قاعدة البيانات ومجلد uploads أولاً.' => 'Back up the database and the uploads folder first.', 'سيتم حذف جميع البيانات نهائياً. هل أنت متأكد؟' => 'All data will be deleted permanently. Are you sure?',
    'اكتب RESET لتأكيد الحذف' => 'Type RESET to confirm deletion', 'كلمة مرورك الحالية' => 'Your current password', 'حذف جميع البيانات واستعادة الوضع الافتراضي' => 'Delete all data and restore defaults', 'لم تتم الاستعادة: اكتب RESET بالضبط وأدخل كلمة مرورك الصحيحة.' => 'Not restored: type RESET exactly and enter your correct password.',
    'تمت استعادة النظام إلى وضعه الافتراضي. حُذفت كل البيانات وبقي حسابك.' => 'The system was restored to its default state. All data was deleted and your account was kept.',    '؟' => '?', 'سحاب الافتراضي' => 'Sahab default', 'ثيم عربي بسيط ومتجاوب يدعم RTL والوضع الداكن.' => 'A simple, responsive theme supporting RTL and dark mode.', 'نموذج التواصل' => 'Contact form',
